const source=$('Preparar contexto de memoria').first().json;
const raw=$json.text ?? $json.output ?? $json.response ?? '';
let d; try{d=JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```$/,'').trim());}catch(e){d={intent:'UNKNOWN',confidence:0,risk:'HIGH'};}
const allowed=['BILLING','TECH_SUPPORT','SALES','CUSTOMER_SUCCESS','UNKNOWN'];
return [{json:{...source,intent:allowed.includes(d.intent)?d.intent:'UNKNOWN',confidence:Math.max(0,Math.min(1,Number(d.confidence??0))),risk:['LOW','MEDIUM','HIGH'].includes(d.risk)?d.risk:'HIGH'}}];

const base=$('Normalizar contrato Router').first().json;
return $input.all().map(item=>({json:{...base,...item.json,
 timestamp:new Date().toISOString(),status:item.json.status??'success',
 worker:item.json.worker??base.intent??'N/D',
 respuesta:String(item.json.respuesta??item.json.output??item.json.text??'Recibimos tu solicitud y la estamos revisando.'),
 requires_human:Boolean(item.json.requires_human??false)}}));

const input=$('Input de prueba').first().json;
const rows=$input.all().map(i=>i.json).filter(r=>r && r.session_id===input.session_id);
const m=rows[0]??{};
return [{json:{...input,memoria_existe:Boolean(m.session_id),
 resumen_consolidado:m.resumen_consolidado && m.resumen_consolidado!=='Sin memoria previa'?m.resumen_consolidado:'',
 estado_caso:m.estado_caso??'NUEVO',datos_clave:m.datos_clave??'',
 historial_pendiente:m.historial_pendiente??'',
 contador_mensajes:Number(m.contador_mensajes??0),
 mensajes_desde_resumen:Number(m.mensajes_desde_resumen??0)}}];

const base=$('Preparar contexto de memoria').first().json;
return $input.all().map(item=>{const j={...base,...item.json};
 const pendiente=[base.historial_pendiente||'',`Cliente: ${base.original_input}\nAgente: ${j.respuesta||''}`].filter(Boolean).join('\n---\n');
 const n=Number(base.mensajes_desde_resumen||0)+1;
 return {json:{...j,contador_mensajes:Number(base.contador_mensajes||0)+1,
 mensajes_desde_resumen:n,historial_pendiente:pendiente,requiere_resumen:n>=5}};
});

