const base=$('Actualizar contador de mensajes').first().json;
const raw=$json.text??$json.output??$json.response??'';
let d;try{d=JSON.parse(String(raw).replace(/^```(?:json)?\s*/i,'').replace(/```$/,'').trim());}catch(e){d={asunto_principal:base.intent,puntos_clave:[base.historial_pendiente],accion_requerida:'',estado_caso:base.estado_caso};}
return [{json:{...base,resumen_consolidado:[d.asunto_principal,...(Array.isArray(d.puntos_clave)?d.puntos_clave:[]),d.accion_requerida].filter(Boolean).join(' | '),
datos_clave:JSON.stringify({puntos_clave:d.puntos_clave??[],accion_requerida:d.accion_requerida??''}),
estado_caso:d.estado_caso||base.estado_caso||'EN_PROCESO',historial_pendiente:'',mensajes_desde_resumen:0,
fecha_actualizacion:new Date().toLocaleString('sv-SE',{timeZone:'America/Argentina/Buenos_Aires'})}}];
